    "html": "<div class=\"dec-app\">\n  <header class=\"dec-header\">\n    <div class=\"dec-brand\">\n      <span style=\"font-size:1.8rem\">⚖️</span>\n      <h2>ChoiceMatrix Weighted Analyzer</h2>\n    </div>\n  </header>\n\n  <div class=\"dec-card\">\n    <table class=\"dec-table\">\n      <thead>\n        <tr>\n          <th>Option Name</th>\n          <th>Salary (x3)</th>\n          <th>Culture (x2)</th>\n          <th>Growth (x3)</th>\n          <th>Total Score</th>\n        </tr>\n      </thead>\n      <tbody id=\"dec-table-body\"></tbody>\n    </table>\n  </div>\n</div>",
    "css": "* { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }\nbody { background: #060913; color: #fff; min-height: 100vh; padding: 16px; }\n.dec-app { max-width: 850px; margin: 0 auto; }\n.dec-header { display: flex; align-items: center; gap: 10px; margin-bottom: 16px; border-bottom: 1px solid rgba(255, 255, 255, 0.08); padding-bottom: 12px; }\n.dec-card { background: #0f172a; border-radius: 12px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.08); }\n.dec-table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }\n.dec-table th { background: #020617; padding: 12px 14px; text-align: left; color: #94a3b8; font-size: 0.75rem; text-transform: uppercase; border-bottom: 1px solid rgba(255, 255, 255, 0.08); }\n.dec-table td { padding: 12px 14px; border-bottom: 1px solid rgba(255, 255, 255, 0.04); }\n.dec-score-badge { background: rgba(16, 185, 129, 0.2); color: #34d399; font-weight: 900; padding: 4px 10px; border-radius: 10px; }",
    "js": "(function() {\n  const options = [\n    { name: 'Option A: FinTech Lead', c1: 9, c2: 7, c3: 9 },\n    { name: 'Option B: AI Startup Founder', c1: 6, c2: 9, c3: 10 },\n    { name: 'Option C: Big Tech Enterprise', c1: 10, c2: 6, c3: 7 }\n  ];\n\n  const tbody = document.getElementById('dec-table-body');\n  options.forEach(o => {\n    o.total = (o.c1 * 3) + (o.c2 * 2) + (o.c3 * 3);\n  });\n  options.sort((a, b) => b.total - a.total);\n\n  tbody.innerHTML = '';\n  options.forEach(o => {\n    const tr = document.createElement('tr');\n    tr.innerHTML = `\n      <td><strong>${o.name}</strong></td>\n      <td>${o.c1} / 10</td>\n      <td>${o.c2} / 10</td>\n      <td>${o.c3} / 10</td>\n      <td><span class=\"dec-score-badge\">${o.total} pts</span></td>\n    `;\n    tbody.appendChild(tr);\n  });\n})();"
